s 17592186165995] [:db/retract 17592186165992 :answer-field/choices 17592186165996] [:db/retract 17592186165992 :answer-field/choices 17592186165997] {:db/id 17592186166872 :knowledge-point/questions ["question-21d74430-9169-5f5c-9745-dbb6cae86953" "question-826a3dfa-4e58-52b9-b4cc-53a7b2b826d4" "question-c62464eb-da81-57d3-9709-e91e0d4b8042"] :db/ensure [:knowledge-point/validate]} {:db/id 17592186166725 :question/problem "$\newcommand{\sech}{\mathop{\rm sech}\nolimits}
