$$" :question/difficulty :question.difficulty/moderate :db/ensure [:question/validate]} {:db/id 17592186165992 :answer-field/correct "answer-44e24fff-6edb-58dd-b6c8-7731cb263263" :answer-field/choices ["answer-9c651855-a335-5bd9-bf70-edb22dff84f8" "answer-454d23bc-df8f-5fb0-9ac4-bbc97aefba45" "answer-4e3e4413-d9ee-532c-ae52-619bdac2ce6d" "answer-5985a81f-c958-57c9-9d4b-af828a400130" "answer-44e24fff-6edb-58dd-b6c8-7731cb263263"] :db/ensure [:answer-field/validate]} {:db/id "answer-9c651855-a335-5bd9-bf70-edb22dff84f8" :answer/id #uuid "9c651855-a335-5bd9-bf70-edb22dff84f8" :answer/type :answer.type/math :answer/value "{cosh}^{2}⁡x+{sinh}^{2}⁡x=-1" :db/ensure [:answer/validate]} {:db/id "answer-454d23bc-df8f-5fb0-9ac4-bbc97aefba45" :answer/id #uuid "454d23bc-df8f-5fb0-9ac4-bbc97aefba45" :answer/type :answer.type/math :answer/value "{cosh}^{2}⁡x+{sinh}^{2}⁡x=1" :db/ensure [:answer/validate]} {:db/id "answer-4e3e4413-d9ee-532c-ae52-619bdac2ce6d" :answer/id #uuid "4e3e4413-d9ee-532c-ae52-619bdac2ce6d" :answer/type :answer.type/math :answer/value "{cosh}^{2}⁡x+{sinh}^{2}⁡x=e" :db/ensure [:answer/validate]} {:db/id "answer-5985a81f-c958-57c9-9d4b-af828a400130" :answer/id #uuid "5985a81f-c958-57c9-9d4b-af828a400130" :answer/type :answer.type/math :answer/value "{cosh}^{2}⁡x-{sinh}^{2}⁡x=-1" :db/ensure [:answer/validate]} {:db/id "answer-44e24fff-6edb-58dd-b6c8-7731cb263263" :answer/id #uuid "44e24fff-6edb-58dd-b6c8-7731cb263263" :answer/type :answer.type/math :answer/value "{cosh}^{2}⁡x-{sinh}^{2}⁡x=1" :db/ensure [:answer/validate]} {:db/id "question-826a3dfa-4e58-52b9-b4cc-53a7b2b826d4" :question/id #uuid "826a3dfa-4e58-52b9-b4cc-53a7b2b826d4" :question/math-academy-id "q-138949" :question/problem "$$
