ic Growth Models With First-Order ODEs" :activity/type :activity.type/review :activity/scope 17592186048578 :activity/course 17592186046645 :activity/steps ["step-0d501e7d-a406-5c5a-a298-944dab97f015" "step-b86f1c28-4218-562a-a0c4-16e6a30b7655" "step-a9bc41cf-00be-5e52-9c2e-495ad57846b2" "step-4e024194-1784-50c8-99d5-8c713e4608d3" "step-8b7d7adf-7ba8-5309-91c3-8926ca95fe88"] :activity/first-step "step-0d501e7d-a406-5c5a-a298-944dab97f015" :db/ensure [:activity/validate]} {:db/id "step-0d501e7d-a406-5c5a-a298-944dab97f015" :step/id #uuid "0d501e7d-a406-5c5a-a298-944dab97f015" :step/content 17592186351556 :step/next "step-b86f1c28-4218-562a-a0c4-16e6a30b7655" :db/ensure [:step/validate]} {:db/id "step-b86f1c28-4218-562a-a0c4-16e6a30b7655" :step/id #uuid "b86f1c28-4218-562a-a0c4-16e6a30b7655" :step/content "question-aac8b725-2415-58f2-86b7-ef6ffd39cf4e" :step/next "step-a9bc41cf-00be-5e52-9c2e-495ad57846b2" :db/ensure [:step/validate]} {:db/id "step-a9bc41cf-00be-5e52-9c2e-495ad57846b2" :step/id #uuid "a9bc41cf-00be-5e52-9c2e-495ad57846b2" :step/content "question-8b4b9134-52af-5188-95f0-9a0da05afadf" :step/next "step-4e024194-1784-50c8-99d5-8c713e4608d3" :db/ensure [:step/validate]} {:db/id "step-4e024194-1784-50c8-99d5-8c713e4608d3" :step/id #uuid "4e024194-1784-50c8-99d5-8c713e4608d3" :step/content "question-d2dfce9f-843a-50f1-956d-65c7968632c5" :step/next "step-8b7d7adf-7ba8-5309-91c3-8926ca95fe88" :db/ensure [:step/validate]} {:db/id "step-8b7d7adf-7ba8-5309-91c3-8926ca95fe88" :step/id #uuid "8b7d7adf-7ba8-5309-91c3-8926ca95fe88" :step/content "question-9f125700-0b98-51e1-a020-af8c1b00c96f" :db/ensure [:step/validate]} [:db/retract 17592186134082 :question/answer-fields 17592186130648] [:db/retract 17592186134086 :question/answer-fields 17592186130672] {:db/id "activity-b4a753ff-d7f8-5373-9dfa-b6d7d7b72e09" :activity/id #uuid "b4a753ff-d7f8-5373-9dfa-b6d7d7b72e09" :activity/title "Line Integrals With Respect to X and Y" :activity/type :activity.type/review :activity/scope 17592186051000 :activity/course 17592186046660 :activity/steps ["step-8bd15231-6077-5acd-b210-63ea5dfd7b32" "step-67e62851-cb57-5f03-806b-78bd3a0fae63" "step-23b5296c-9050-57da-ab12-b54ca52a68dd" "step-de912477-5c57-5e4d-865f-02d49e044bb5" "step-8338d321-9ae2-5f16-a804-d4198a730ec4"] :activity/first-step "step-8bd15231-6077-5acd-b210-63ea5dfd7b32" :db/ensure [:activity/validate]} {:db/id "step-8bd15231-6077-5acd-b210-63ea5dfd7b32" :step/id #uuid "8bd15231-6077-5acd-b210-63ea5dfd7b32" :step/content 17592186134082 :step/next "step-67e62851-cb57-5f03-806b-78bd3a0fae63" :db/ensure [:step/validate]} {:db/id "step-67e62851-cb57-5f03-806b-78bd3a0fae63" :step/id #uuid "67e62851-cb57-5f03-806b-78bd3a0fae63" :step/content 17592186134083 :step/next "step-23b5296c-9050-57da-ab12-b54ca52a68dd" :db/ensure [:step/validate]} {:db/id "step-23b5296c-9050-57da-ab12-b54ca52a68dd" :step/id #uuid "23b5296c-9050-57da-ab12-b54ca52a68dd" :step/content 17592186259605 :step/next "step-de912477-5c57-5e4d-865f-02d49e044bb5" :db/ensure [:step/validate]} {:db/id "step-de912477-5c57-5e4d-865f-02d49e044bb5" :step/id #uuid "de912477-5c57-5e4d-865f-02d49e044bb5" :step/content 17592186134086 :step/next "step-8338d321-9ae2-5f16-a804-d4198a730ec4" :db/ensure [:step/validate]} {:db/id "step-8338d321-9ae2-5f16-a804-d4198a730ec4" :step/id #uuid "8338d321-9ae2-5f16-a804-d4198a730ec4" :step/content 17592186387498 :db/ensure [:step/validate]} {:db/id 17592186096743 :knowledge-point/questions ["question-d26b4fec-f259-5757-943d-c92ed32d5a4b" "question-f593ac8e-7a29-5f43-82ff-aea84a5ba69c"] :db/ensure [:knowledge-point/validate]} {:db/id "question-d26b4fec-f259-5757-943d-c92ed32d5a4b" :question/id #uuid "d26b4fec-f259-5757-943d-c92ed32d5a4b" :question/math-academy-id "q-10859" :question/problem "What is the limit of the sequence ${a}_{n}=\frac{(2{n}^{2}+3)(2{n}^{2}-3)}{2n(5{n}^{3}-1)}$ for $n\ge 1?$" :question/worked-solution "First, we multiply out the numerator and denominator of the sequence and get

$$
{a}_{n}=\frac{(2{n}^{2}+3)(2{n}^{2}-3)}{2n(5{n}^{3}-1)}=\frac{4{n}^{4}-9}{10{n}^{4}-2n}.
$$

So to find the limit, we will need to compute

$$
{lim}_{n\to \infty }{a}_{n}={lim}_{n\to \infty }\frac{4{n}^{4}-9}{10{n}^{4}-2n}.
$$

The dominant term in the denominator is $10{n}^{4},$ so we divide the numerator and the denominator by ${n}^{4}$ and get

$$
\begin{aligned}{lim}_{n\to \infty }\frac{4{n}^{4}-9}{10{n}^{4}-2n} & ={lim}_{n\to \infty }\frac{(\frac{4{n}^{4}}{{n}^{4}}-\frac{9}{{n}^{4}})}{(\frac{10{n}^{4}}{{n}^{4}}-\frac{2n}{{n}^{4}})} \\  & ={lim}_{n\to \infty }\frac{(4-\frac{9}{{n}^{4}})}{(10-\frac{2}{{n}^{3}})} \\  & =\frac{4-0}{10-0} \\  & =\frac{2}{5}.\end{aligned}
$$

Consequently, the sequence converges and its limit is $\frac{2}{5}.$" :question/difficulty :question.difficulty/moderate :question/answer-fields ["answer-field-5d7987cd-9189-59ea-8be9-6b86123a7745"] :db/ensure [:question/validate]} {:db/id "answer-field-5d7987cd-9189-59ea-8be9-6b86123a7745" :answer-field/id #uuid "5d7987cd-9189-59ea-8be9-6b86123a7745" :answer-field/key "selection" :answer-field/type :answer-field.type/radio :answer-field/correct "answer-78d710b0-36b9-5af3-afee-6ec469874bb2" :answer-field/choices ["answer-1a58b002-6268-59f9-8d62-d5780db00a57" "answer-975f8bf1-29e1-5e24-8470-e16a6bceb947" "answer-78d710b0-36b9-5af3-afee-6ec469874bb2" "answer-e2169256-da89-5b10-b1ae-084da0651fe3" "answer-1084ac63-ef9b-56cc-bcb8-ef50cf2a751e"] :db/ensure [:answer-field/validate]} {:db/id "answer-1a58b002-6268-59f9-8d62-d5780db00a57" :answer/id #uuid "1a58b002-6268-59f9-8d62-d5780db00a57" :answer/type :answer.type/math :answer/value "0" :db/ensure [:answer/validate]} {:db/id "answer-975f8bf1-29e1-5e24-8470-e16a6bceb947" :answer/id #uuid "975f8bf1-29e1-5e24-8470-e16a6bceb947" :answer/type :answer.type/math :answer/value "1" :db/ensure [:answer/validate]} {:db/id "answer-78d710b0-36b9-5af3-afee-6ec469874bb2" :answer/id #uuid "78d710b0-36b9-5af3-afee-6ec469874bb2" :answer/type :answer.type/math :answer/value "\frac{2}{5}" :db/ensure [:answer/validate]} {:db/id "answer-e2169256-da89-5b10-b1ae-084da0651fe3" :answer/id #uuid "e2169256-da89-5b10-b1ae-084da0651fe3" :answer/type :answer.type/math :answer/value "\frac{5}{2}" :db/ensure [:answer/validate]} {:db/id "answer-1084ac63-ef9b-56cc-bcb8-ef50cf2a751e" :answer/id #uuid "1084ac63-ef9b-56cc-bcb8-ef50cf2a751e" :answer/type :answer.type/text :answer/value "The sequence diverges" :db/ensure [:answer/validate]} {:db/id "question-f593ac8e-7a29-5f43-82ff-aea84a5ba69c" :question/id #uuid "f593ac8e-7a29-5f43-82ff-aea84a5ba69c" :question/math-academy-id "q-123332" :question/problem "What is the limit of the sequence ${a}_{n}=\frac{(3n-2)(3n+2)}{n(1-9n)}$ for $n\ge 1?$" :question/worked-solution "First, we multiply out the numerator and denominator of the sequence and get

$$
{a}_{n}=\frac{(3n-2)(3n+2)}{n(1-9n)}=\frac{9{n}^{2}-4}{n-9{n}^{2}}.
$$

So to find the limit, we will need to compute

$$
{lim}_{n\to \infty }{a}_{n}={lim}_{n\to \infty }\frac{9{n}^{2}-4}{n-9{n}^{2}}.
$$

The dominant term in the denominator is $-9{n}^{2},$ so we divide the numerator and the denominator by ${n}^{2}$ and get

$$
\begin{aligned}{lim}_{n\to \infty }\frac{9{n}^{2}-4}{n-9{n}^{2}} & ={lim}_{n\to \infty }\frac{(\frac{9{n}^{2}}{{n}^{2}}-\frac{4}{{n}^{2}})}{(\frac{n}{{n}^{2}}-\frac{9{n}^{2}}{{n}^{2}})} \\  & ={lim}_{n\to \infty }\frac{(9-\frac{4}{{n}^{2}})}{(\frac{1}{n}-9)} \\  & =\frac{9-0}{0-9} \\  & =-1.\end{aligned}
$$

Consequently, the sequence converges and its limit is $-1.$" :question/difficulty :question.difficulty/moderate :question/answer-fields ["answer-field-0759db57-b8ce-5f50-b46e-8b442e52ee62"] :db/ensure [:question/validate]} {:db/id "answer-field-0759db57-b8ce-5f50-b46e-8b442e52ee62" :answer-field/id #uuid "0759db57-b8ce-5f50-b46e-8b442e52ee62" :answer-field/key "selection" :answer-field/type :answer-field.type/radio :answer-field/correct "answer-ddcaa7ca-0c0c-5d03-adf8-e0d7f6832969" :answer-field/choices ["answer-ddcaa7ca-0c0c-5d03-adf8-e0d7f6832969" "answer-973d5ba1-9f1d-5d54-a5a6-681dae8dfc0a" "answer-ba2648e8-3c45-5b47-8bbc-61b0f969add5" "answer-5ca0fb74-d0d3-5f86-be12-a821fb96b41e" "answer-fa7ed841-cc61-56c4-b2ed-0e53c44c292c"] :db/ensure [:answer-field/validate]} {:db/id "answer-ddcaa7ca-0c0c-5d03-adf8-e0d7f6832969" :answer/id #uuid "ddcaa7ca-0c0c-5d03-adf8-e0d7f6832969" :answer/type :answer.type/math :answer/value "-1" :db/ensure [:answer/validate]} {:db/id "answer-973d5ba1-9f1d-5d54-a5a6-681dae8dfc0a" :answer/id #uuid "973d5ba1-9f1d-5d54-a5a6-681dae8dfc0a" :answer/type :answer.type/math :answer/value "0" :db/ensure [:answer/validate]} {:db/id "answer-ba2648e8-3c45-5b47-8bbc-61b0f969add5" :answer/id #uuid "ba2648e8-3c45-5b47-8bbc-61b0f969add5" :answer/type :answer.type/math :answer/value "9" :db/ensure [:answer/validate]} {:db/id "answer-5ca0fb74-d0d3-5f86-be12-a821fb96b41e" :answer/id #uuid "5ca0fb74-d0d3-5f86-be12-a821fb96b41e" :answer/type :answer.type/math :answer/value "\frac{4}{9}" :db/ensure [:answer/validate]} {:db/id "answer-fa7ed841-cc61-56c4-b2ed-0e53c44c292c" :answer/id #uuid "fa7ed841-cc61-56c4-b2ed-0e53c44c292c" :answer/type :answer.type/text :answer/value "The sequence diverges" :db/ensure [:answer/validate]} {:db/id 17592186096741 :knowledge-point/questions ["question-548006ed-ff60-5fe8-9b17-af5147ac7aae"] :db/ensure [:knowledge-point/validate]} {:db/id "question-548006ed-ff60-5fe8-9b17-af5147ac7aae" :question/id #uuid "548006ed-ff60-5fe8-9b17-af5147ac7aae" :question/math-academy-id "q-347972" :question/problem "What is the limit of the sequence ${a}_{n}=\frac{12n+1}{3n}$ for $n\ge 1?$

