$$"] ["question-8fef57fc-2f55-531e-87c9-45485e34049e" :question/difficulty :question.difficulty/easy] ["answer-field-ec396184-e874-5ee9-9738-287768ca0067" :answer-field/id #uuid "ec396184-e874-5ee9-9738-287768ca0067"] ["answer-471a4b7a-98d9-5684-a4fb-e5881f1be8ed" :answer/id #uuid "471a4b7a-98d9-5684-a4fb-e5881f1be8ed"] ["answer-471a4b7a-98d9-5684-a4fb-e5881f1be8ed" :answer/type :answer.type/math] ["answer-471a4b7a-98d9-5684-a4fb-e5881f1be8ed" :answer/value "\frac{2}{3}"] ["answer-field-ec396184-e874-5ee9-9738-287768ca0067" :answer-field/key "field-1"] ["answer-field-ec396184-e874-5ee9-9738-287768ca0067" :answer-field/type :answer-field.type/blank] ["answer-field-ec396184-e874-5ee9-9738-287768ca0067" :answer-field/correct "answer-471a4b7a-98d9-5684-a4fb-e5881f1be8ed"] ["answer-field-ec396184-e874-5ee9-9738-287768ca0067" :answer-field/choices "answer-471a4b7a-98d9-5684-a4fb-e5881f1be8ed"] ["question-8fef57fc-2f55-531e-87c9-45485e34049e" :question/answer-fields "answer-field-ec396184-e874-5ee9-9738-287768ca0067"] [17592186054839 :knowledge-point/questions "question-8fef57fc-2f55-531e-87c9-45485e34049e"] ["question-a728363a-21de-5465-8925-c66dae64d6b5" :question/id #uuid "a728363a-21de-5465-8925-c66dae64d6b5"] ["question-a728363a-21de-5465-8925-c66dae64d6b5" :question/math-academy-id "q-68624"] ["question-a728363a-21de-5465-8925-c66dae64d6b5" :question/problem "${(-6\times 9)}^{8}=$"] ["question-a728363a-21de-5465-8925-c66dae64d6b5" :question/worked-solution "To raise the product of two numbers to the power of $8$, we can raise each number to the power of $8,$ and then multiply:

