aa50d8-7e59-5ec3-baec-32c35fa91223" :answer-field/choices "answer-63e7d7b2-6328-5a7c-9e7b-fa3dbce3eabb"] ["answer-field-02aa50d8-7e59-5ec3-baec-32c35fa91223" :answer-field/choices "answer-9667e35e-f889-55cd-8df1-5a84f2a0d662"] ["answer-field-02aa50d8-7e59-5ec3-baec-32c35fa91223" :answer-field/choices "answer-f6c3fe8d-00a3-53be-a31e-4a67a046510c"] ["answer-field-02aa50d8-7e59-5ec3-baec-32c35fa91223" :answer-field/choices "answer-b68eee8c-221b-58d9-95b5-d015aa6fa3b2"] ["question-8bf7e480-fb51-579e-b130-139151e7ecc4" :question/answer-fields "answer-field-02aa50d8-7e59-5ec3-baec-32c35fa91223"] [17592186138394 :knowledge-point/questions "question-8bf7e480-fb51-579e-b130-139151e7ecc4"] ["question-32edbf40-91ab-5dc2-911c-42534beb5cff" :question/id #uuid "32edbf40-91ab-5dc2-911c-42534beb5cff"] ["question-32edbf40-91ab-5dc2-911c-42534beb5cff" :question/math-academy-id "q-318354"] ["question-32edbf40-91ab-5dc2-911c-42534beb5cff" :question/problem "What number is $175%$ greater than $48?$"] ["question-32edbf40-91ab-5dc2-911c-42534beb5cff" :question/worked-solution "To find a number $175%$ *greater than* $48,$ we apply a new percentage of

$$
100%+175%=275%.
$$

We begin by converting the percentage to a decimal:

$$
275%=\frac{275}{100}=2.75
$$

So, to find a number that is $175%$ greater than $48,$ we multiply $48$ by $2.75:$

$$
2.75\cdot 48=132
$$

Therefore, the number that is $175%$ greater than $48$ is $132.$"] ["question-32edbf40-91ab-5dc2-911c-42534beb5cff" :question/difficulty :question.difficulty/easy] ["answer-field-98df2e4f-b683-5bb4-8a2e-794e7d7efd73" :answer-field/id #uuid "98df2e4f-b683-5bb4-8a2e-794e7d7efd73"] ["answer-b97144c0-81e0-5543-82e8-e60b900bad57" :answer/id #uuid "b97144c0-81e0-5543-82e8-e60b900bad57"] ["answer-b97144c0-81e0-5543-82e8-e60b900bad57" :answer/type :answer.type/math] ["answer-b97144c0-81e0-5543-82e8-e60b900bad57" :answer/value "110"] ["answer-5f957550-490c-5d15-93b3-98e6be45e35b" :answer/id #uuid "5f957550-490c-5d15-93b3-98e6be45e35b"] ["answer-5f957550-490c-5d15-93b3-98e6be45e35b" :answer/type :answer.type/math] ["answer-5f957550-490c-5d15-93b3-98e6be45e35b" :answer/value "120"] ["answer-a0177ecd-9269-57dd-ac6c-b48ee7ad95ff" :answer/id #uuid "a0177ecd-9269-57dd-ac6c-b48ee7ad95ff"] ["answer-a0177ecd-9269-57dd-ac6c-b48ee7ad95ff" :answer/type :answer.type/math] ["answer-a0177ecd-9269-57dd-ac6c-b48ee7ad95ff" :answer/value "125"] ["answer-9647ff7c-56ee-5eaa-b169-213ba236e2d9" :answer/id #uuid "9647ff7c-56ee-5eaa-b169-213ba236e2d9"] ["answer-9647ff7c-56ee-5eaa-b169-213ba236e2d9" :answer/type :answer.type/math] ["answer-9647ff7c-56ee-5eaa-b169-213ba236e2d9" :answer/value "132"] ["answer-4c122ba6-cc81-5732-b3b3-5c73d49cce35" :answer/id #uuid "4c122ba6-cc81-5732-b3b3-5c73d49cce35"] ["answer-4c122ba6-cc81-5732-b3b3-5c73d49cce35" :answer/type :answer.type/math] ["answer-4c122ba6-cc81-5732-b3b3-5c73d49cce35" :answer/value "140"] ["answer-field-98df2e4f-b683-5bb4-8a2e-794e7d7efd73" :answer-field/key "selection"] ["answer-field-98df2e4f-b683-5bb4-8a2e-794e7d7efd73" :answer-field/type :answer-field.type/radio] ["answer-field-98df2e4f-b683-5bb4-8a2e-794e7d7efd73" :answer-field/correct "answer-9647ff7c-56ee-5eaa-b169-213ba236e2d9"] ["answer-field-98df2e4f-b683-5bb4-8a2e-794e7d7efd73" :answer-field/choices "answer-b97144c0-81e0-5543-82e8-e60b900bad57"] ["answer-field-98df2e4f-b683-5bb4-8a2e-