$$
\begin{aligned}3{w}^{4}-{w}^{3}-5{w}^{4} & = \\ (3{w}^{4}-5{w}^{4})-{w}^{3} & = \\ (3-5){w}^{4}-{w}^{3} & = \\ -2{w}^{4}-{w}^{3}\end{aligned}
$$"] ["question-8b3fdd80-83cc-5d53-85c1-0216b4942139" :question/difficulty :question.difficulty/easy] ["answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de" :answer-field/id #uuid "c4f49a27-fbe6-5211-9e4e-77c7312508de"] ["answer-d3ee0861-9665-55bd-98e5-b09f0500d4c5" :answer/id #uuid "d3ee0861-9665-55bd-98e5-b09f0500d4c5"] ["answer-d3ee0861-9665-55bd-98e5-b09f0500d4c5" :answer/type :answer.type/math] ["answer-d3ee0861-9665-55bd-98e5-b09f0500d4c5" :answer/value "-2{w}^{4}-5{w}^{3}"] ["answer-231fa41e-7562-58c3-bc53-a8af642e063c" :answer/id #uuid "231fa41e-7562-58c3-bc53-a8af642e063c"] ["answer-231fa41e-7562-58c3-bc53-a8af642e063c" :answer/type :answer.type/math] ["answer-231fa41e-7562-58c3-bc53-a8af642e063c" :answer/value "-2{w}^{4}-{w}^{3}"] ["answer-fd9c33f9-8e43-5ba3-8d78-df3475ffcd16" :answer/id #uuid "fd9c33f9-8e43-5ba3-8d78-df3475ffcd16"] ["answer-fd9c33f9-8e43-5ba3-8d78-df3475ffcd16" :answer/type :answer.type/math] ["answer-fd9c33f9-8e43-5ba3-8d78-df3475ffcd16" :answer/value "2{w}^{4}-5{w}^{3}"] ["answer-52e7dc11-9cb1-5f72-b61c-ed22849bf163" :answer/id #uuid "52e7dc11-9cb1-5f72-b61c-ed22849bf163"] ["answer-52e7dc11-9cb1-5f72-b61c-ed22849bf163" :answer/type :answer.type/math] ["answer-52e7dc11-9cb1-5f72-b61c-ed22849bf163" :answer/value "3{w}^{4}-6{w}^{3}"] ["answer-8f86123d-e422-5dce-9146-cf89e8645b54" :answer/id #uuid "8f86123d-e422-5dce-9146-cf89e8645b54"] ["answer-8f86123d-e422-5dce-9146-cf89e8645b54" :answer/type :answer.type/math] ["answer-8f86123d-e422-5dce-9146-cf89e8645b54" :answer/value "3{w}^{4}-{w}^{3}"] ["answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de" :answer-field/key "selection"] ["answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de" :answer-field/type :answer-field.type/radio] ["answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de" :answer-field/correct "answer-231fa41e-7562-58c3-bc53-a8af642e063c"] ["answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de" :answer-field/choices "answer-d3ee0861-9665-55bd-98e5-b09f0500d4c5"] ["answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de" :answer-field/choices "answer-231fa41e-7562-58c3-bc53-a8af642e063c"] ["answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de" :answer-field/choices "answer-fd9c33f9-8e43-5ba3-8d78-df3475ffcd16"] ["answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de" :answer-field/choices "answer-52e7dc11-9cb1-5f72-b61c-ed22849bf163"] ["answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de" :answer-field/choices "answer-8f86123d-e422-5dce-9146-cf89e8645b54"] ["question-8b3fdd80-83cc-5d53-85c1-0216b4942139" :question/answer-fields "answer-field-c4f49a27-fbe6-5211-9e4e-77c7312508de"] [17592186119768 :knowledge-point/questions "question-8b3fdd80-83cc-5d53-85c1-0216b4942139"] ["question-8f0c5a6d-560b-5b20-a886-377893e98cd2" :question/id #uuid "8f0c5a6d-560b-5b20-a886-377893e98cd2"] ["question-8f0c5a6d-560b-5b20-a886-377893e98cd2" :question/math-academy-id "q-154082"] ["question-8f0c5a6d-560b-5b20-a886-377893e98cd2" :question/problem "The mass $m$ of a tablet PC measures $314.7\,\text{g}$ to the nearest tenth of a gram. Determine the upper and lower bounds of this measurement."] ["question-8f0c5a6d-560b-5b20-a886-377893e98cd2" :question/worked-solution "Our measurement is given to the nearest $0.1\,\text{g}.$ So, the greatest possible error of this measurement is

$$
\frac{0.1\,\text{g}}{2}=0.05\,\text{g}.
$$

Therefore, we can calculate the lower and upper bounds of this measurement as follows:

$$
\begin{aligned}\text{lower bound} & =314.7\,\text{g}-0.05\,\text{g} \\  & =314.65\,\text{g} \\ \text{upper bound} & =314.7\,\text{g}+0.05\,\text{g} \\  & =314.75\,\text{g}\end{aligned}
$$

Since the exact value of $m$ lies between the lower and upper bound, we conclude that

$$
314.65\,\text{g}\le m<314.75\,\text{g}.
$$"] ["question-8f0c5a6d-560b-5b20-a886-377893e98cd2" :question/difficulty :question.difficulty/easy] ["answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99" :answer-field/id #uuid "6435960d-f51a-52e7-94e7-a76e47e9ec99"] ["answer-86ccb7e9-64a7-58a7-9d0c-22ade13bddc2" :answer/id #uuid "86ccb7e9-64a7-58a7-9d0c-22ade13bddc2"] ["answer-86ccb7e9-64a7-58a7-9d0c-22ade13bddc2" :answer/type :answer.type/math] ["answer-86ccb7e9-64a7-58a7-9d0c-22ade13bddc2" :answer/value "313.7\,\text{g}\le m<315.7\,\text{g}"] ["answer-06b7ceac-a5dd-5a5e-81f6-5093daac715f" :answer/id #uuid "06b7ceac-a5dd-5a5e-81f6-5093daac715f"] ["answer-06b7ceac-a5dd-5a5e-81f6-5093daac715f" :answer/type :answer.type/math] ["answer-06b7ceac-a5dd-5a5e-81f6-5093daac715f" :answer/value "314.65\,\text{g}\le m<314.75\,\text{g}"] ["answer-5237a001-734d-52ba-8325-09127dd19a3d" :answer/id #uuid "5237a001-734d-52ba-8325-09127dd19a3d"] ["answer-5237a001-734d-52ba-8325-09127dd19a3d" :answer/type :answer.type/math] ["answer-5237a001-734d-52ba-8325-09127dd19a3d" :answer/value "314.695\,\text{g}\le m<314.705\,\text{g}"] ["answer-334f31b7-f7be-595d-b52c-848908f510f2" :answer/id #uuid "334f31b7-f7be-595d-b52c-848908f510f2"] ["answer-334f31b7-f7be-595d-b52c-848908f510f2" :answer/type :answer.type/math] ["answer-334f31b7-f7be-595d-b52c-848908f510f2" :answer/value "314.69\,\text{g}\le m<314.71\,\text{g}"] ["answer-52df3fc4-f30c-5656-9770-f6b6852fee06" :answer/id #uuid "52df3fc4-f30c-5656-9770-f6b6852fee06"] ["answer-52df3fc4-f30c-5656-9770-f6b6852fee06" :answer/type :answer.type/math] ["answer-52df3fc4-f30c-5656-9770-f6b6852fee06" :answer/value "314.6\,\text{g}\le m<314.8\,\text{g}"] ["answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99" :answer-field/key "selection"] ["answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99" :answer-field/type :answer-field.type/radio] ["answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99" :answer-field/correct "answer-06b7ceac-a5dd-5a5e-81f6-5093daac715f"] ["answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99" :answer-field/choices "answer-86ccb7e9-64a7-58a7-9d0c-22ade13bddc2"] ["answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99" :answer-field/choices "answer-06b7ceac-a5dd-5a5e-81f6-5093daac715f"] ["answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99" :answer-field/choices "answer-5237a001-734d-52ba-8325-09127dd19a3d"] ["answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99" :answer-field/choices "answer-334f31b7-f7be-595d-b52c-848908f510f2"] ["answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99" :answer-field/choices "answer-52df3fc4-f30c-5656-9770-f6b6852fee06"] ["question-8f0c5a6d-560b-5b20-a886-377893e98cd2" :question/answer-fields "answer-field-6435960d-f51a-52e7-94e7-a76e47e9ec99"] [17592186138388 :knowledge-point/questions "question-8f0c5a6d-560b-5b20-a886-377893e98cd2"] [17592186074397 :question/worked-solution "One of the points belonging to the graph is $(10,15).$

Let's write the ratio $10:15$ as a fraction:

$$
\frac{10}{15}
$$

We can simplify this fraction by dividing both the numerator and the denominator by $5$:

$$
\begin{aligned}\frac{10÷5}{15÷5} & =\frac{2}{3}\end{aligned}
$$

So the ratio of lemon juice to water is $2:3.$"] [17592186074397 :question/difficulty :question.difficulty/hard] ["answer-9e2d1ca2-29a3-590d-8b3a-8e4797c313f5" :answer/id #uuid "9e2d1ca2-29a3-590d-8b3a-8e4797c313f5"] ["answer-9e2d1ca2-29a3-590d-8b3a-8e4797c313f5" :answer/type :answer.type/math] ["answer-9e2d1ca2-29a3-590d-8b3a-8e4797c313f5" :answer/value "1:5"] ["answer-d74c804c-a8d1-59e6-9899-b3b34ec27cb2" :answer/id #uuid "d74c804c-a8d1-59e6-9899-b3b34ec27cb2"] ["answer-d74c804c-a8d1-59e6-9899-b3b34ec27cb2" :answer/type :answer.type/math] ["answer-d74c804c-a8d1-59e6-9899-b3b34ec27cb2" :answer/value "2:3"] ["answer-3309d42c-e7de-5e1b-be51-6b077a257c48" :answer/id #uuid "3309d42c-e7de-5e1b-be51-6b077a257c48"] ["answer-3309d42c-e7de-5e1b-be51-6b077a257c48" :answer/type :answer.type/math] ["answer-3309d42c-e7de-5e1b-be51-6b077a257c48" :answer/value "2:5"] ["answer-c96f6581-7aac-56c8-9f71-0a776b002031" :answer/id #uuid "c96f6581-7aac-56c8-9f71-0a776b002031"] ["answer-c96f6581-7aac-56c8-9f71-0a776b002031" :answer/type :answer.type/math] ["answer-c96f6581-7aac-56c8-9f71-0a776b002031" :answer/value "3:4"] ["answer-68e267a2-c19e-5d1c-8c01-8f92fa4013d1" :answer/id #uuid "68e267a2-c19e-5d1c-8c01-8f92fa4013d1"] ["answer-68e267a2-c19e-5d1c-8c01-8f92fa4013d1" :answer/type :answer.type/math] ["answer-68e267a2-c19e-5d1c-8c01-8f92fa4013d1" :answer/value "5:8"] [17592186072620 :answer-field/correct "answer-d74c804c-a8d1-59e6-9899-b3b34ec27cb2"] [17592186072620 :answer-field/choices "answer-9e2d1ca2-29a3-590d-8b3a-8e4797c313f5"] [17592186072620 :answer-field/choices "answer-d74c804c-a8d1-59e6-9899-b3b34ec27cb2"] [17592186072620 :answer-field/choices "answer-3309d42c-e7de-5e1b-be51-6b077a257c48"] [17592186072620 :answer-field/choices "answer-c96f6581-7aac-56c8-9f71-0a776b002031"] [17592186072620 :answer-field/choices "answer-68e267a2-c19e-5d1c-8c01-8f92fa4013d1"] ["question-ac3e396f-e9ff-515e-95c3-ddf87162b016" :question/id #uuid "ac3e396f-e9ff-515e-95c3-ddf87162b016"] ["question-ac3e396f-e9ff-515e-95c3-ddf87162b016" :question/math-academy-id "q-68844"] ["question-ac3e396f-e9ff-515e-95c3-ddf87162b016" :question/problem "Maria has a bank account at LJB Bank. She has an overdraft facility authorized by this bank. Her bank balance on Monday was $-$40.00.$ To reduce her debt, Maria decides to make a deposit of $$18.60$ into her bank account on the following Tuesday. What is Maria's balance at the end of the day on Tuesday?"] ["question-ac3e396f-e9ff-515e-95c3-ddf87162b016" :question/worked-solution "To determine the balance at the end of the day on Tuesday, we must add the amount of money Maria deposited to the starting balance. This gives

$$
-$40.00+$18.60=-$21.40.
$$

