138537 :knowledge-point/questions "question-8a9682b8-c5c3-5a53-a91f-bba592503325"] ["question-4305d4d8-cadf-560e-80db-63776f30d2a1" :question/id #uuid "4305d4d8-cadf-560e-80db-63776f30d2a1"] ["question-4305d4d8-cadf-560e-80db-63776f30d2a1" :question/math-academy-id "q-100739"] ["question-4305d4d8-cadf-560e-80db-63776f30d2a1" :question/problem "${(\frac{1}{5})}^{3}=$"] ["question-4305d4d8-cadf-560e-80db-63776f30d2a1" :question/worked-solution "To raise the fraction to the power of $3$, we must raise both the numerator and the denominator to the power of $3:$

$$
