er-field-3ee4b5b3-c121-55ee-96bd-54041a866832" :answer-field/choices "answer-43b8f5fb-30a4-58cc-b827-a3c6c0f1627e"] ["answer-field-3ee4b5b3-c121-55ee-96bd-54041a866832" :answer-field/choices "answer-af0d5166-e6c8-504d-975f-ece6f9efdfce"] ["answer-field-3ee4b5b3-c121-55ee-96bd-54041a866832" :answer-field/choices "answer-12436895-69cb-503c-8085-217ca08ec281"] ["answer-field-3ee4b5b3-c121-55ee-96bd-54041a866832" :answer-field/choices "answer-4eec80dc-bf63-5e26-a70a-c9df0a844d2d"] ["answer-field-3ee4b5b3-c121-55ee-96bd-54041a866832" :answer-field/choices "answer-d6cf2865-18ea-59ba-9dab-3d90e49f0104"] ["question-21c1c6c9-f8f1-50f1-a9ef-3d13b0e5c684" :question/answer-fields "answer-field-3ee4b5b3-c121-55ee-96bd-54041a866832"] [17592186096629 :knowledge-point/questions "question-21c1c6c9-f8f1-50f1-a9ef-3d13b0e5c684"] ["question-2bcca121-9116-5327-93c6-12a3a1649264" :question/id #uuid "2bcca121-9116-5327-93c6-12a3a1649264"] ["question-2bcca121-9116-5327-93c6-12a3a1649264" :question/math-academy-id "q-345038"] ["question-2bcca121-9116-5327-93c6-12a3a1649264" :question/problem "The area under the curve $y=(x+1)^{2}$ between $x=-1$ and $x=3$ and the $x$-axis is approximated by a right Riemann sum using $4$ subintervals of equal length. What is the expression for the right Riemann sum ${S}_{R}$ in sigma notation?

