45b4-0d19-5a65-9da0-878c4f37d052"] ["answer-field-9980a067-163c-5305-b9d5-aeb44a51e2ee" :answer-field/choices "answer-4e278261-12a2-522a-865f-2ee4f991690d"] ["answer-field-9980a067-163c-5305-b9d5-aeb44a51e2ee" :answer-field/choices "answer-95c87fe0-b27d-523b-b97f-283a3892f373"] ["answer-field-9980a067-163c-5305-b9d5-aeb44a51e2ee" :answer-field/choices "answer-c4625cbc-5b19-59bd-9eb5-2085cc809466"] ["answer-field-9980a067-163c-5305-b9d5-aeb44a51e2ee" :answer-field/choices "answer-ad6e45b4-0d19-5a65-9da0-878c4f37d052"] ["answer-field-9980a067-163c-5305-b9d5-aeb44a51e2ee" :answer-field/choices "answer-c24f6fe3-8f3b-5e4f-87ee-cd603ef7bb00"] ["question-b9e3535a-6a10-557b-a90a-dcbee5f059a0" :question/answer-fields "answer-field-9980a067-163c-5305-b9d5-aeb44a51e2ee"] [17592186162096 :knowledge-point/questions "question-b9e3535a-6a10-557b-a90a-dcbee5f059a0"] ["question-6a4bb009-1382-5d80-b122-5cf6749f1552" :question/id #uuid "6a4bb009-1382-5d80-b122-5cf6749f1552"] ["question-6a4bb009-1382-5d80-b122-5cf6749f1552" :question/math-academy-id "q-138615"] ["question-6a4bb009-1382-5d80-b122-5cf6749f1552" :question/problem "$$
