1e2"] ["step-0346e43f-4ec3-54fd-a36a-83c457ba540d" :step/next "step-23e83d25-72e7-5ce0-8291-4514123ca24b"] ["step-23e83d25-72e7-5ce0-8291-4514123ca24b" :step/content "question-2f2cb4c0-5e13-5762-90d1-d095feb4a65e"] ["step-23e83d25-72e7-5ce0-8291-4514123ca24b" :step/next "step-d14ef892-c3d1-5aad-87b3-30b8a9ceff03"] ["step-d14ef892-c3d1-5aad-87b3-30b8a9ceff03" :step/content "question-d39bfe0e-e6e3-509a-9ccb-2651e206d7a8"] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/title "The Sample Covariance Matrix"] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/type :activity.type/review] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/scope 17592186050911] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/course 17592186046658] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/steps "step-6d56aefc-11ae-57d8-922f-7a3f39b19dcc"] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/steps "step-c3d9e78e-168e-5b62-9c51-d4a45ca0bbdb"] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/steps "step-0346e43f-4ec3-54fd-a36a-83c457ba540d"] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/steps "step-23e83d25-72e7-5ce0-8291-4514123ca24b"] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/steps "step-d14ef892-c3d1-5aad-87b3-30b8a9ceff03"] ["activity-e9f30801-05f6-5733-bfd9-7a227c36223a" :activity/first-step "step-6d56aefc-11ae-57d8-922f-7a3f39b19dcc"] ["question-50970995-9b99-52ed-ae6b-c20b930d578c" :question/id #uuid "50970995-9b99-52ed-ae6b-c20b930d578c"] ["question-50970995-9b99-52ed-ae6b-c20b930d578c" :question/math-academy-id "q-9537"] ["question-50970995-9b99-52ed-ae6b-c20b930d578c" :question/problem "![](images/50/5034bb902aadd151cc1a28764e054dbdd6a694ad653f50557e5fc208c8ec2342.png)

Find the arc length of the polar curve $r=1+\operatorname{cos}⁡\theta $ for $0\le \theta \le \pi $ (shown in blue in the diagram above).

*Hint: You may wish to use the following identity: $\operatorname{cos}⁡(\frac{x}{2})=\sqrt{\frac{1+\operatorname{cos}⁡x}{2}}.$*"] ["question-50970995-9b99-52ed-ae6b-c20b930d578c" :question/worked-solution "The arc length $L$ of a polar curve $r=r(\theta )$ is given by

$$
L={\int }_{{\theta }_{1}}^{{\theta }_{2}}\sqrt{{r}^{2}+{(\frac{\text{d}r}{\text{d}\theta })}^{2}}\,\text{d}\theta .
$$

Since $r=1+\operatorname{cos}⁡\theta ,$ we have

$$
\frac{\text{d}r}{\text{d}\theta }=-\operatorname{sin}⁡\theta .
$$

Therefore, the arc length is

$$
\begin{aligned}L & ={\int }_{{\theta }_{1}}^{{\theta }_{2}}\sqrt{{r}^{2}+{(\frac{\text{d}r}{\text{d}\theta })}^{2}}\,\text{d}\theta  \\  & ={\int }_{0}^{\pi }\sqrt{(1+\operatorname{cos}⁡\theta )^{2}+{(-\operatorname{sin}⁡\theta )}^{2}}\,\text{d}\theta  \\  & ={\int }_{0}^{\pi }\sqrt{1+2\operatorname{cos}⁡\theta +{cos}^{2}⁡\theta +{sin}^{2}⁡\theta }\,\text{d}\theta  \\  & ={\int }_{0}^{\pi }\sqrt{1+2\operatorname{cos}⁡\theta +1}\,\text{d}\theta  \\  & ={\int }_{0}^{\pi }\sqrt{2+2\operatorname{cos}⁡\theta }\,\text{d}\theta  \\  & =\sqrt{2}{\int }_{0}^{\pi }\sqrt{1+\operatorname{cos}⁡\theta }\,\text{d}\theta \end{aligned}
$$

Now, we recall the identity for $\operatorname{cos}⁡(\frac{x}{2}):$

$$
\operatorname{cos}⁡(\frac{x}{2})=\sqrt{\frac{1+\operatorname{cos}⁡x}{2}}
$$

Using $x=\theta $ in the above identity, the integral can be rewritten as follows:

$$
\begin{aligned}L & =\sqrt{2}{\int }_{0}^{\pi }\sqrt{2{cos}^{2}⁡(\frac{\theta }{2})}\,\text{d}\theta  \\  & =\sqrt{2}\cdot \sqrt{2}\cdot {\int }_{0}^{\pi }\operatorname{cos}⁡(\frac{\theta }{2})\,\text{d}\theta  \\  & ={2\cdot 2(\operatorname{sin}⁡(\frac{\theta }{2}))|}_{0}^{\pi } \\  & =4(\operatorname{sin}⁡(\frac{\pi }{2})-\operatorname{sin}⁡0) \\  & =4(1-0) \\  & =4.\end{aligned}
$$"] ["question-50970995-9b99-52ed-ae6b-c20b930d578c" :question/difficulty :question.difficulty/moderate] ["answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c" :answer-field/id #uuid "e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c"] ["answer-f6d4553a-62e1-59c9-8854-5587cc1e9c71" :answer/id #uuid "f6d4553a-62e1-59c9-8854-5587cc1e9c71"] ["answer-f6d4553a-62e1-59c9-8854-5587cc1e9c71" :answer/type :answer.type/math] ["answer-f6d4553a-62e1-59c9-8854-5587cc1e9c71" :answer/value "1"] ["answer-cc05201a-8232-5a04-8ce3-e3ac354a9f76" :answer/id #uuid "cc05201a-8232-5a04-8ce3-e3ac354a9f76"] ["answer-cc05201a-8232-5a04-8ce3-e3ac354a9f76" :answer/type :answer.type/math] ["answer-cc05201a-8232-5a04-8ce3-e3ac354a9f76" :answer/value "2"] ["answer-2ada2e3d-0769-5b5a-85e6-218cbeec1c89" :answer/id #uuid "2ada2e3d-0769-5b5a-85e6-218cbeec1c89"] ["answer-2ada2e3d-0769-5b5a-85e6-218cbeec1c89" :answer/type :answer.type/math] ["answer-2ada2e3d-0769-5b5a-85e6-218cbeec1c89" :answer/value "2\sqrt{2}"] ["answer-725bc856-b7c0-56dc-9518-bdc1f5428c77" :answer/id #uuid "725bc856-b7c0-56dc-9518-bdc1f5428c77"] ["answer-725bc856-b7c0-56dc-9518-bdc1f5428c77" :answer/type :answer.type/math] ["answer-725bc856-b7c0-56dc-9518-bdc1f5428c77" :answer/value "4"] ["answer-4b33b710-8754-5317-ad8d-edc5c3f9305d" :answer/id #uuid "4b33b710-8754-5317-ad8d-edc5c3f9305d"] ["answer-4b33b710-8754-5317-ad8d-edc5c3f9305d" :answer/type :answer.type/math] ["answer-4b33b710-8754-5317-ad8d-edc5c3f9305d" :answer/value "4\sqrt{2}"] ["answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c" :answer-field/key "selection"] ["answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c" :answer-field/type :answer-field.type/radio] ["answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c" :answer-field/correct "answer-725bc856-b7c0-56dc-9518-bdc1f5428c77"] ["answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c" :answer-field/choices "answer-f6d4553a-62e1-59c9-8854-5587cc1e9c71"] ["answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c" :answer-field/choices "answer-cc05201a-8232-5a04-8ce3-e3ac354a9f76"] ["answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c" :answer-field/choices "answer-2ada2e3d-0769-5b5a-85e6-218cbeec1c89"] ["answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c" :answer-field/choices "answer-725bc856-b7c0-56dc-9518-bdc1f5428c77"] ["answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c" :answer-field/choices "answer-4b33b710-8754-5317-ad8d-edc5c3f9305d"] ["question-50970995-9b99-52ed-ae6b-c20b930d578c" :question/answer-fields "answer-field-e6fa46cf-d1f0-5fd4-a76c-c62db6438a9c"] [17592186092374 :knowledge-point/questions "question-50970995-9b99-52ed-ae6b-c20b930d578c"] ["question-d80dc7c0-9327-55d2-9040-e9261d08f05c" :question/id #uuid "d80dc7c0-9327-55d2-9040-e9261d08f05c"] ["question-d80dc7c0-9327-55d2-9040-e9261d08f05c" :question/math-academy-id "q-349991"] ["question-d80dc7c0-9327-55d2-9040-e9261d08f05c" :question/problem "The total amount of money $M(t)$ in a charity’s fundraising account $t$ days after the first day of a campaign is given by the function

$$
M(t)=1500+{\int }_{0}^{t}(3{x}^{2}-27)\,\text{d}x,
$$

where $M$ is measured in dollars, and $t\ge 0$ is the time (in days) since the first day of the campaign.

Find the time when the total amount is minimum, and how much money was in the account at that time.

The minimum amount is
$$$
{{field-1}}
