es "answer-041cf703-252a-5a82-af4d-e39fe9281f89"] ["answer-field-4c49559e-e9c1-5193-b92b-63cd7b8e9ab9" :answer-field/choices "answer-0f05675a-7366-5451-836b-a7a34485b9da"] ["answer-field-4c49559e-e9c1-5193-b92b-63cd7b8e9ab9" :answer-field/choices "answer-1ea52371-3342-5c52-8943-370aaad27a07"] ["answer-field-4c49559e-e9c1-5193-b92b-63cd7b8e9ab9" :answer-field/choices "answer-334cd414-155f-577b-83d1-656c2d080e14"] ["question-15f86877-8327-59b3-8e4f-e39de73201de" :question/answer-fields "answer-field-4c49559e-e9c1-5193-b92b-63cd7b8e9ab9"] [17592186073781 :knowledge-point/questions "question-15f86877-8327-59b3-8e4f-e39de73201de"] ["question-abee8b7a-4a45-595d-8f90-0e0bbc3678c1" :question/id #uuid "abee8b7a-4a45-595d-8f90-0e0bbc3678c1"] ["question-abee8b7a-4a45-595d-8f90-0e0bbc3678c1" :question/math-academy-id "q-4056"] ["question-abee8b7a-4a45-595d-8f90-0e0bbc3678c1" :question/problem "The point $Q(-3,1)$ is shifted $2$ units up, reflected across the $y$-axis, and then shifted $1$ unit to the left. What is the resulting point?"] ["question-abee8b7a-4a45-595d-8f90-0e0bbc3678c1" :question/worked-solution "Let's recall the functional representations of our three transformations:

- A shift of $2$ units up can be represented by the function 

$$
(x,y)↦(x,y+2).
$$

- A reflection in the $y$-axis can be represented by the function 

$$
(x,y)↦(-x,y).
$$

- A shift of $1$ unit to the left can be represented by the function 

$$
(x,y)↦(x-1,y).
$$

Let's apply the given transformations to the point $Q$ using our functions:

First, we apply the shift. The image of the point $(-3,1)$ under the shift is

$$
(-3,1)↦(-3,1+2)=(-3,3).
$$



Then, we apply the reflection. The image of the point $(-3,3)$ under the reflection is

$$
(-3,3)↦(3,3).
$$

Finally, we apply the second shift by $1$ unit to the left. The image of the point $(3,3)$ under the shift is

$$
(3,3)↦(3-1,3)=(2,3).
$$



Therefore, the resulting point is $(2,3).$"] ["question-abee8b7a-4a45-595d-8f90-0e0bbc3678c1" :question/difficulty :question.difficulty/moderate] ["answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf" :answer-field/id #uuid "4699a690-a8bd-5581-b11e-7163244e6dcf"] ["answer-d1814799-e689-53a9-80c0-138645ff6068" :answer/id #uuid "d1814799-e689-53a9-80c0-138645ff6068"] ["answer-d1814799-e689-53a9-80c0-138645ff6068" :answer/type :answer.type/math] ["answer-d1814799-e689-53a9-80c0-138645ff6068" :answer/value "(-2,-3)"] ["answer-a4e5ce62-ea3a-5f89-be1a-a44d806e3912" :answer/id #uuid "a4e5ce62-ea3a-5f89-be1a-a44d806e3912"] ["answer-a4e5ce62-ea3a-5f89-be1a-a44d806e3912" :answer/type :answer.type/math] ["answer-a4e5ce62-ea3a-5f89-be1a-a44d806e3912" :answer/value "(-3,-4)"] ["answer-3d6aa5e1-96ad-5af2-b67a-d52b21a1d422" :answer/id #uuid "3d6aa5e1-96ad-5af2-b67a-d52b21a1d422"] ["answer-3d6aa5e1-96ad-5af2-b67a-d52b21a1d422" :answer/type :answer.type/math] ["answer-3d6aa5e1-96ad-5af2-b67a-d52b21a1d422" :answer/value "(-4,-3)"] ["answer-ea7eef76-ed62-5f78-aa7d-5f5fcde472d4" :answer/id #uuid "ea7eef76-ed62-5f78-aa7d-5f5fcde472d4"] ["answer-ea7eef76-ed62-5f78-aa7d-5f5fcde472d4" :answer/type :answer.type/math] ["answer-ea7eef76-ed62-5f78-aa7d-5f5fcde472d4" :answer/value "(1,0)"] ["answer-e044b7d5-8486-58d6-b3fe-085072e21840" :answer/id #uuid "e044b7d5-8486-58d6-b3fe-085072e21840"] ["answer-e044b7d5-8486-58d6-b3fe-085072e21840" :answer/type :answer.type/math] ["answer-e044b7d5-8486-58d6-b3fe-085072e21840" :answer/value "(2,3)"] ["answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf" :answer-field/key "selection"] ["answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf" :answer-field/type :answer-field.type/radio] ["answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf" :answer-field/correct "answer-e044b7d5-8486-58d6-b3fe-085072e21840"] ["answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf" :answer-field/choices "answer-d1814799-e689-53a9-80c0-138645ff6068"] ["answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf" :answer-field/choices "answer-a4e5ce62-ea3a-5f89-be1a-a44d806e3912"] ["answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf" :answer-field/choices "answer-3d6aa5e1-96ad-5af2-b67a-d52b21a1d422"] ["answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf" :answer-field/choices "answer-ea7eef76-ed62-5f78-aa7d-5f5fcde472d4"] ["answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf" :answer-field/choices "answer-e044b7d5-8486-58d6-b3fe-085072e21840"] ["question-abee8b7a-4a45-595d-8f90-0e0bbc3678c1" :question/answer-fields "answer-field-4699a690-a8bd-5581-b11e-7163244e6dcf"] [17592186073904 :knowledge-point/questions "question-abee8b7a-4a45-595d-8f90-0e0bbc3678c1"] ["question-5d698685-38f5-5e4a-b709-e155fb9c6b96" :question/id #uuid "5d698685-38f5-5e4a-b709-e155fb9c6b96"] ["question-5d698685-38f5-5e4a-b709-e155fb9c6b96" :question/math-academy-id "q-14379"] ["question-5d698685-38f5-5e4a-b709-e155fb9c6b96" :question/problem "The point $P(-21,17)$ is acted on by a shift of $7$ units down followed by reflection across the line $y=x.$ What is the image of $P$ under this transformation?"] ["question-5d698685-38f5-5e4a-b709-e155fb9c6b96" :question/worked-solution "Let's recall the functional representations of our two transformations:

- A shift of $7$ units down can be represented by the function 

$$
(x,y)↦(x,y-7).
$$

- A reflection across the line $y=x$ can be represented by the function

$$
(x,y)↦(y,x).
$$

Let's apply the given transformations to the point $P$ using our functions:

First, we apply the shift. The image of the point $(-21,17)$ under the shift is

$$
(-21,17)↦(-21,17-7)=(-21,10).
$$



Then, we apply the reflection. The image of the point $(-21,10)$ under the reflection is

$$
(-21,10)↦(10,-21).
$$

