ield/key "selection"] ["answer-field-77a8b135-2107-5f15-9423-d337960d5809" :answer-field/type :answer-field.type/radio] ["answer-field-77a8b135-2107-5f15-9423-d337960d5809" :answer-field/correct "answer-42a7b526-d419-53d4-998e-26b9d74a5719"] ["answer-field-77a8b135-2107-5f15-9423-d337960d5809" :answer-field/choices "answer-2ae34e21-7c67-51c7-ad42-919ff37db938"] ["answer-field-77a8b135-2107-5f15-9423-d337960d5809" :answer-field/choices "answer-42a7b526-d419-53d4-998e-26b9d74a5719"] ["answer-field-77a8b135-2107-5f15-9423-d337960d5809" :answer-field/choices "answer-1b719625-bf60-5411-8eb1-a84362f7e2c3"] ["answer-field-77a8b135-2107-5f15-9423-d337960d5809" :answer-field/choices "answer-147ffdc0-24a2-5d99-94c8-4dc089c3bee3"] ["answer-field-77a8b135-2107-5f15-9423-d337960d5809" :answer-field/choices "answer-aa19e49d-5812-5cd6-9b3c-f4c9d4845763"] ["question-87e86a6c-a43c-5891-bdf0-9aeef9e7dff1" :question/answer-fields "answer-field-77a8b135-2107-5f15-9423-d337960d5809"] [17592186073779 :knowledge-point/questions "question-87e86a6c-a43c-5891-bdf0-9aeef9e7dff1"] [17592186074182 :question/problem "The point $P(-5,-2)$ is rotated ${270}^{∘}$ counterclockwise about the origin $O$ and then translated according to the function $(x,y)↦(x+p,y+q).$ If the image of $P$ under this sequence of transformations is $(2,-9),$ then $p+q=$"] [17592186074182 :question/worked-solution "Let's apply the given transformations.

A rotation of ${270}^{∘}$ counterclockwise about $O$ can be represented by 

$$
(x,y)↦(y,-x).
$$

Applying this to the point $P,$ we get

$$
(-5,-2)↦(-2,5).
$$

Now, applying the translation to $(-2,5),$ we get

$$
(-2,5)↦(-2+p,5+q).
$$



Since the resulting point is $(2,-9),$ by equating the $x$- and $y$-coordinates, we obtain

$$
\begin{aligned}\{\begin{aligned}-2+p=2 \\ 5+q=-9\end{aligned}\,⟹\,\{\begin{aligned}p=4 \\ q=-14.\end{aligned}\end{aligned}
$$

Finally, 

$$
p-q=4+(-14)=-10.
$$"] [17592186074182 :question/difficulty :question.difficulty/hard] [17592186071330 :answer-field/correct 17592186071335] ["question-76343f99-bb5f-5787-863a-2557d071c09b" :question/id #uuid "76343f99-bb5f-5787-863a-2557d071c09b"] ["question-76343f99-bb5f-5787-863a-2557d071c09b" :question/math-academy-id "q-88408"] ["question-76343f99-bb5f-5787-863a-2557d071c09b" :question/problem "The point $P(2,3)$ is rotated ${90}^{∘}$ counterclockwise about the origin $O$ and then translated according to the function $(x,y)↦(x-p,y+q).$ If the image of $P$ under this sequence of transformations is $(-1,5),$ then $p+q=$"] ["question-76343f99-bb5f-5787-863a-2557d071c09b" :question/worked-solution "Let's apply the given transformations.

A rotation of ${90}^{∘}$ counterclockwise about $O$ can be represented by 

$$
(x,y)↦(-y,x).
$$

Applying this to the point $P,$ we get

$$
(2,3)↦(-3,2).
$$

Now, applying the translation to $(-3,2),$ we get

$$
(-3,2)↦(-3-p,2+q).
$$



Since the resulting point is $(-1,5),$ by equating the $x$- and $y$-coordinates, we obtain

$$
\begin{aligned}\{\begin{aligned}-3-p=-1 \\ 2+q=5\end{aligned}\,⟹\,\{\begin{aligned}p=-2 \\ q=3.\end{aligned}\end{aligned}
$$

Finally, 

$$
p+q=(-2)+3=1.
$$"] ["question-76343f99-bb5f-5787-863a-2557d071c09b" :question/difficulty :question.difficulty/hard] ["answer-field-b39c4d94-12fb-5a15-b6bb-bc1e15c955c5" :answer-field/id #uuid "b39c4d94-12fb-5a15-b6bb-bc1e15c955c5"] ["answer-3f1012f6-ac99-5e4e-a9f6-7a1a7f4d837b" :answer/id #uuid "3f1012f6-ac99-5e4e-a9f6-7a1a7f4d837b"] ["answer-3f1012f6-ac99-5e4e-a9f6-7a1a7f4d837b" :answer/type :answer.type/math] ["answer-3f1012f6-ac99-5e4e-a9f6-7a1a7f4d837b" :answer/value "-1"] ["answer-9648dece-0d06-5613-b589-cdd0fc59e342" :answer/id #uuid "9648dece-0d06-5613-b589-cdd0fc59e342"] ["answer-9648dece-0d06-5613-b589-cdd0fc59e342" :answer/type :answer.type/math] ["answer-9648dece-0d06-5613-b589-cdd0fc59e342" :answer/value "-2"] ["answer-ced0514e-753d-5d75-af21-617042730647" :answer/id #uuid "ced0514e-753d-5d75-af21-617042730647"] ["answer-ced0514e-753d-5d75-af21-617042730647" :answer/type :answer.type/math] ["answer-ced0514e-753d-5d75-af21-617042730647" :answer/value "0"] ["answer-15c607d4-a926-5be5-9a79-37c070202dbc" :answer/id #uuid "15c607d4-a926-5be5-9a79-37c070202dbc"] ["answer-15c607d4-a926-5be5-9a79-37c070202dbc" :answer/type :answer.type/math] ["answer-15c607d4-a926-5be5-9a79-37c070202dbc" :answer/value "1"] ["answer-4dff97b4-92fa-577d-9da9-9c6d62f99972" :answer/id #uuid "4dff97b4-92fa-577d-9da9-9c6d62f99972"] ["answer-4dff97b4-92fa-577d-9da9-9c6d62f99972" :answer/type :answer.type/math] ["answer-4dff97b4-92fa-577d-9da9-9c6d62f99972" :answer/value "3"] ["answer-field-b39c4d94-12fb-5a15-b6bb-bc1e15c955c5" :answer-field/key "selection"] ["answer-field-b39c4d94-12fb-5a15-b6bb-bc1e15c955c5" :answer-field/type :answer-field.type/radio] ["answer-field-b39c4d94-12fb-5a15-b6bb-bc1e15c955c5" :answer-field/correct "answer-15c607d4-a926-5be5-9a79-37c070202dbc"] ["answer-field-b39c4d94-12fb-5a15-b6bb-bc1e15c955c5" :answer-field/choices "answer-3f1012f6-ac99-5e4e-a9f6-7a1a7f4d837b"] ["answer-field-b39c4d94-12fb-5a15-b6bb-bc1e15c955c5" :answer-field/choices "answer-9648dece-0d06-5613-b589-cd